def relabeled_clone(self, relabels):
    clone = self.__class__.__new__(self.__class__)
    clone.__dict__.update(self.__dict__)

    # Handle relabeling for alias if it exists
    if hasattr(clone, 'alias') and clone.alias in relabels:
        clone.alias = relabels[clone.alias]

    # Handle relabeling for other attributes that might reference columns
    for attr in clone.__dict__:
        # Check if the attribute is a string that matches a relabel key
        if isinstance(clone.__dict__[attr], str) and clone.__dict__[attr] in relabels:
            clone.__dict__[attr] = relabels[clone.__dict__[attr]]

        # Check if the attribute is a list of strings
        if isinstance(clone.__dict__[attr], list):
            clone.__dict__[attr] = [relabels.get(item, item) if isinstance(item, str) else item
                                    for item in clone.__dict__[attr]]

        # Check for other nested structures that might need relabeling
        if hasattr(clone.__dict__[attr], 'relabeled_clone'):
            clone.__dict__[attr] = clone.__dict__[attr].relabeled_clone(relabels)

    return clone
